public final class PhoneCredits {
    static final Object[] CACHE_LOCKS=new Object[16];static {for(int n=0;n<CACHE_LOCKS.length;n++)CACHE_LOCKS[n]=new Object();}static final ExecutorService WORK=Executors.newFixedThreadPool(2);static final long DAY=86400000L;final DataStore data;final File cache;final DiscoveryClient art;
    static {String[][] words={{"Cast & crew","طاقم التمثيل والعمل"},{"Directed by","إخراج"},{"Written by","كتابة"},{"Known for","أشهر الأعمال"},{"Filmography","الأعمال"},{"In your library","في مكتبتك"},{"✓ Watched","✓ تمت المشاهدة"},{"No filmography is available yet.","لا تتوفر أعمال حاليًا."},{"‹ Back","‹ رجوع"},{"Person details","تفاصيل الشخص"},{"Previews when you rest on a title","معاينات عند التوقف على عنوان"},{"Trailer","إعلان"},{"The title itself","العنوان نفسه"},{"Off","إيقاف"},{"Unknown year","سنة غير معروفة"}};for(String[] w:words)Loc.AR.put(w[0],w[1]);}
    PhoneCredits(DataStore d){data=d;cache=new File(d.context.getCacheDir(),"credits");cache.mkdirs();art=new DiscoveryClient(d.context);}
    static String imdb(JSONObject item){String id=item.optString("imdb",item.optString("id"));return id.matches("tt[0-9]+")?id:"";}
    static boolean movie(JSONObject item){return item.has("movie")?item.optBoolean("movie"):item.optString("noirType",item.optString("type")).equals("movie");}
    Object read(String url,long age)throws Exception{synchronized(CACHE_LOCKS[Math.floorMod((cache.getPath()+url).hashCode(),CACHE_LOCKS.length)]){return readLocked(url,age);}}
    Object readLocked(String url,long age)throws Exception{URL parsed=new URL(url);if(!parsed.getProtocol().equals("https"))throw new IOException("HTTPS required");File file=new File(cache,DiscoveryClient.hash(url)+".json");if(file.exists()&&file.length()<=2*1024*1024&&file.lastModified()>System.currentTimeMillis()-age)return new JSONTokener(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8)).nextValue();try{byte[] bytes=fetch(url);Object json=new JSONTokener(new String(bytes,StandardCharsets.UTF_8)).nextValue();DiscoveryClient.write(file,bytes);prune();return json;}catch(Exception e){if(file.exists()&&file.length()<=2*1024*1024&&file.lastModified()>System.currentTimeMillis()-30*DAY)return new JSONTokener(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8)).nextValue();throw e;}}
    static byte[] fetch(String url)throws Exception{for(int n=0;n<4;n++){URL parsed=new URL(url);if(!parsed.getProtocol().equals("https"))throw new IOException("HTTPS required");HttpsURLConnection c=(HttpsURLConnection)parsed.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(7000);c.setRequestProperty("User-Agent","Noir-Android/0.5");try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("Missing redirect");url=new URL(parsed,location).toString();continue;}if(status!=200)throw new IOException("Metadata unavailable");try(InputStream in=c.getInputStream()){return DataStore.read(in,2*1024*1024);}}finally{c.disconnect();}}throw new IOException("Redirect limit");}
    synchronized void prune(){File[] files=cache.listFiles();if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());long bytes=0;for(int n=0;n<files.length;n++){bytes+=files[n].length();if(n>=192||bytes>24*1024*1024||files[n].lastModified()<System.currentTimeMillis()-30*DAY)files[n].delete();}}
    JSONObject metadata(JSONObject item)throws Exception{String id=imdb(item);if(id.isEmpty())return new JSONObject();Object value=read("https://v3-cinemeta.strem.io/meta/"+(movie(item)?"movie":"series")+"/"+id+".json",7*DAY);return value instanceof JSONObject?((JSONObject)value).optJSONObject("meta"):new JSONObject();}
    JSONObject load(JSONObject item){JSONObject result=new JSONObject();JSONArray cast=new JSONArray();JSONObject meta=null;try{meta=metadata(item);if(meta!=null){cast=parseCinemeta(meta);DataStore.put(result,"director",names(meta.opt("director")));DataStore.put(result,"writer",names(meta.opt("writer")));}}catch(Exception ignored){}boolean photos=false;for(JSONObject p:DataStore.objects(cast))photos|=!p.optString("photo").isEmpty();if(!movie(item)&&!imdb(item).isEmpty()&&!photos)try{JSONObject show=(JSONObject)read("https://api.tvmaze.com/lookup/shows?imdb="+imdb(item),7*DAY);JSONArray rows=(JSONArray)read("https://api.tvmaze.com/shows/"+show.optInt("id")+"/cast",7*DAY);JSONArray other=parseTvmaze(rows);merge(cast,other);}catch(Exception ignored){}DataStore.put(result,"cast",cast);return result;}
    static String names(Object value){if(value instanceof JSONArray){List<String> names=new ArrayList<>();JSONArray rows=(JSONArray)value;for(int n=0;n<rows.length();n++){Object row=rows.opt(n);String s=row instanceof JSONObject?((JSONObject)row).optString("name"):String.valueOf(row);if(!s.isEmpty()&&!s.equals("null"))names.add(s);}return android.text.TextUtils.join(", ",names);}if(value instanceof JSONObject)return ((JSONObject)value).optString("name");return value==null||value==JSONObject.NULL?"":String.valueOf(value);}
    static JSONObject person(String name,String character,String photo,int tvmaze){JSONObject p=new JSONObject();DataStore.put(p,"name",name);DataStore.put(p,"character",character);DataStore.put(p,"photo",photo.startsWith("https://")?photo:"");if(tvmaze>0)DataStore.put(p,"tvmaze",tvmaze);return p;}
    static JSONArray parseCinemeta(JSONObject meta){JSONArray cast=new JSONArray();JSONObject extras=meta.optJSONObject("app_extras");Object source=extras==null?null:extras.opt("cast");if(!(source instanceof JSONArray)||((JSONArray)source).length()==0)source=meta.opt("credits_cast");if(!(source instanceof JSONArray)||((JSONArray)source).length()==0)source=meta.opt("cast");if(source instanceof JSONArray){JSONArray rows=(JSONArray)source;for(int n=0;n<Math.min(80,rows.length());n++){Object row=rows.opt(n);if(row instanceof JSONObject){JSONObject p=(JSONObject)row;JSONObject nested=p.optJSONObject("person");JSONObject who=nested==null?p:nested;String photo=who.optString("photo",who.optString("profile_path",who.optString("image")));JSONObject image=who.optJSONObject("image");if(image!=null)photo=image.optString("medium",image.optString("original"));if(photo.startsWith("/"))photo="https://image.tmdb.org/t/p/w185"+photo;String character=p.optString("character",p.optString("role"));if(p.optJSONObject("character")!=null)character=p.optJSONObject("character").optString("name");String name=who.optString("name",who.optString("actor"));if(!name.isEmpty())cast.put(person(name,character,photo,0));}else if(row instanceof String&&!((String)row).trim().isEmpty())cast.put(person((String)row,"","",0));}}return cast;}
    static JSONArray parseTvmaze(JSONArray rows){JSONArray cast=new JSONArray();for(JSONObject row:DataStore.objects(rows)){JSONObject p=row.optJSONObject("person"),c=row.optJSONObject("character");if(p==null)continue;JSONObject image=p.optJSONObject("image");cast.put(person(p.optString("name"),c==null?"":c.optString("name"),image==null?"":image.optString("medium",image.optString("original")),p.optInt("id")));if(cast.length()>=80)break;}return cast;}
    static void merge(JSONArray target,JSONArray source){for(JSONObject person:DataStore.objects(source)){JSONObject match=null;for(JSONObject p:DataStore.objects(target))if(p.optString("name").equalsIgnoreCase(person.optString("name"))){match=p;break;}if(match==null)target.put(person);else for(String key:new String[]{"photo","character","tvmaze"})if(match.optString(key).isEmpty()||key.equals("tvmaze"))DataStore.put(match,key,person.opt(key));}}
    static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
    static TextView text(Context c,String value,int size,int color){TextView t=new TextView(c);t.setText(Loc.t(value));t.setTextSize(size);t.setTextColor(color);return t;}
    public static View castStrip(MainActivity a,JSONObject item){return castStrip((Activity)a,item);}
    public static View castStrip(Activity a,JSONObject item){PhoneCredits client=new PhoneCredits(NoirApp.data);JSONObject seed=DataStore.copy(item);LinearLayout host=new LinearLayout(a);host.setOrientation(LinearLayout.VERTICAL);host.setPadding(0,dp(a,18),0,dp(a,18));TextView title=text(a,"Cast & crew",20,MainActivity.WHITE);title.setTypeface(null,Typeface.BOLD);host.addView(title);HorizontalScrollView scroll=new HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);LinearLayout rail=new LinearLayout(a);scroll.addView(rail);host.addView(scroll);for(int n=0;n<5;n++){View skeleton=new View(a);skeleton.setBackground(MainActivity.bg(MainActivity.PANEL,dp(a,40)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(a,72),dp(a,72));lp.setMargins(dp(a,4),dp(a,12),dp(a,16),dp(a,96));rail.addView(skeleton,lp);}WORK.execute(()->{JSONObject credits=client.load(seed);a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed())return;rail.removeAllViews();JSONArray people=credits.optJSONArray("cast");if((people==null||people.length()==0)&&credits.optString("director").isEmpty()&&credits.optString("writer").isEmpty()){host.setVisibility(View.GONE);return;}for(JSONObject person:DataStore.objects(people)){LinearLayout card=new LinearLayout(a);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(dp(a,4),dp(a,12),dp(a,4),dp(a,8));ImageView photo=photo(a,client,person.optString("photo"),true);card.addView(photo,new LinearLayout.LayoutParams(dp(a,72),dp(a,72)));TextView name=text(a,person.optString("name"),13,MainActivity.WHITE);name.setGravity(Gravity.CENTER);name.setMaxLines(2);name.setMinLines(2);name.setPadding(0,dp(a,8),0,0);card.addView(name,new LinearLayout.LayoutParams(-1,dp(a,44)));TextView role=text(a,person.optString("character"),11,MainActivity.MUTED);role.setGravity(Gravity.CENTER);role.setMaxLines(2);card.addView(role,new LinearLayout.LayoutParams(-1,dp(a,34)));card.setContentDescription(person.optString("name"));card.setOnClickListener(v->a.startActivity(new Intent(a,PersonActivity.class).putExtra("person",person.toString()).putExtra("source",seed.toString())));Motion.card(card);rail.addView(card,new LinearLayout.LayoutParams(dp(a,100),dp(a,180)));}for(String key:new String[]{"director","writer"})if(!credits.optString(key).isEmpty()){TextView line=text(a,Loc.t(key.equals("director")?"Directed by":"Written by")+" · "+credits.optString(key),13,MainActivity.MUTED);line.setPadding(0,dp(a,8),0,0);host.addView(line);}Motion.fadeIn(rail);});});return host;}
    static ImageView photo(Activity a,PhoneCredits client,String url,boolean round){ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(MainActivity.bg(Motion.placeholder(url),dp(a,round?100:16)));image.setClipToOutline(true);if(url.startsWith("https://"))WORK.execute(()->{try{Bitmap bitmap=client.art.art(url);a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())Motion.loaded(image,bitmap,url);});}catch(Exception ignored){}});return image;}
    JSONArray filmography(JSONObject person,JSONObject source){LinkedHashMap<String,JSONObject> titles=new LinkedHashMap<>();if(person.optInt("tvmaze")>0)try{JSONArray credits=(JSONArray)read("https://api.tvmaze.com/people/"+person.optInt("tvmaze")+"/castcredits?embed=show",7*DAY);for(JSONObject credit:DataStore.objects(credits)){JSONObject embed=credit.optJSONObject("_embedded"),show=embed==null?null:embed.optJSONObject("show");if(show==null)continue;JSONObject external=show.optJSONObject("externals");String id=external==null?"":external.optString("imdb");if(!id.matches("tt[0-9]+"))continue;JSONObject title=new JSONObject();DataStore.put(title,"id",id);DataStore.put(title,"imdb",id);DataStore.put(title,"name",show.optString("name"));DataStore.put(title,"noirType","series");DataStore.put(title,"year",show.optString("premiered").replaceAll("-.*$",""));JSONObject image=show.optJSONObject("image");if(image!=null)DataStore.put(title,"poster",image.optString("medium"));titles.put(id,title);}}catch(Exception ignored){}if(source!=null&&!imdb(source).isEmpty())titles.put(imdb(source),seed(source));for(JSONObject item:DataStore.objects(data.items()))if(mentions(item,person.optString("name")))titles.put(imdb(item),seed(item));List<File> metadataFiles=new ArrayList<>();for(File directory:new File[]{art.directory,cache}){File[] found=directory.listFiles((dir,name)->name.endsWith(".json"));if(found!=null)Collections.addAll(metadataFiles,found);}File[] files=metadataFiles.toArray(new File[0]);if(files.length>0){Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());for(int n=0;n<Math.min(files.length,192);n++)try{if(files[n].length()>2*1024*1024)continue;JSONObject root=new JSONObject(new String(java.nio.file.Files.readAllBytes(files[n].toPath()),StandardCharsets.UTF_8));JSONObject meta=root.optJSONObject("meta");if(meta!=null&&mentions(meta,person.optString("name")))titles.put(imdb(meta),seed(meta));for(JSONObject metaRow:DataStore.objects(root.optJSONArray("metas")))if(mentions(metaRow,person.optString("name")))titles.put(imdb(metaRow),seed(metaRow));}catch(Exception ignored){}}List<JSONObject> sorted=new ArrayList<>(titles.values());sorted.sort((a,b)->b.optString("year").compareTo(a.optString("year")));JSONArray result=new JSONArray();for(JSONObject title:sorted)if(!imdb(title).isEmpty())result.put(title);return result;}
    static boolean mentions(JSONObject item,String person){for(JSONObject p:DataStore.objects(parseCinemeta(item)))if(p.optString("name").equalsIgnoreCase(person))return true;for(String key:new String[]{"director","writer"}){String people=names(item.opt(key));for(String name:people.split(","))if(name.trim().equalsIgnoreCase(person))return true;}return false;}
    static JSONObject seed(JSONObject item){JSONObject seed=new JSONObject();DataStore.put(seed,"id",imdb(item));DataStore.put(seed,"imdb",imdb(item));DataStore.put(seed,"name",item.optString("name",item.optString("title")));DataStore.put(seed,"noirType",movie(item)?"movie":"series");DataStore.put(seed,"year",item.optString("year",item.optString("releaseInfo")).replaceAll("[^0-9].*$",""));DataStore.put(seed,"poster",item.optString("posterUrl",item.optString("poster")));return seed;}
}
